INSERT INTO public.disciplinary_letters ("id", "letter_number", "letter_type", "personnel_id", "recipient_name", "badge_id", "rank", "issue_date", "effective_date", "violation_category", "severity", "incident_summary", "sanctions", "authorized_by", "status", "notes", "created_at") VALUES ('DIS-001', 'NEG/DIS/TERM/2026/001', 'Dismissal / Termination Letter', 'NEG-022', 'Minto Ganji Romanov', 'PASPAM028', 'Sergeant', '2026-10-12', '2026-10-12', 'Excessive Absenteeism / AWOL', 'Critical / Severe', 'An internal review confirms that Minto Ganji Romanov has been completely inactive and unresponsive for a continuous period of two months, failing to log hours or communicate with his department. System records verify this prolonged absence, establishing a clear violation of company attendance and job abandonment policies. Consequently, it is recommended that Romanov''s employment be formally terminated and all associated corporate access be permanently revoked.', 'Immediate Discharge with Prejudice, Revocation of Guard Badge & Security Clearance, Return of All Armory Equipment', 'Mikhail Orlov G Romanov (Director)', 'Served', '', '2026-10-12T14:17:40.94+00:00') ON CONFLICT (id) DO UPDATE SET "id" = EXCLUDED."id", "letter_number" = EXCLUDED."letter_number", "letter_type" = EXCLUDED."letter_type", "personnel_id" = EXCLUDED."personnel_id", "recipient_name" = EXCLUDED."recipient_name", "badge_id" = EXCLUDED."badge_id", "rank" = EXCLUDED."rank", "issue_date" = EXCLUDED."issue_date", "effective_date" = EXCLUDED."effective_date", "violation_category" = EXCLUDED."violation_category", "severity" = EXCLUDED."severity", "incident_summary" = EXCLUDED."incident_summary", "sanctions" = EXCLUDED."sanctions", "authorized_by" = EXCLUDED."authorized_by", "status" = EXCLUDED."status", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
